-- 04 — OPTIONAL: direct SQL insert of the 1,023 import-ready products
-- Skip this file if you use Admin → Products → Import (recommended).
--
-- This bypasses the backend validation, audit log, and automatic price
-- history. It is guarded so it only runs against an empty product table.
-- Run 03_wipe.sql first. If any statement fails, the transaction rolls back.
--
-- Stock: 741 blank-stock rows were set to 10; existing 5/50 stock was kept.

begin;

do $$
begin
  if (select count(*) from public.product) > 0 then
    raise exception 'product table is not empty; run 03_wipe.sql first';
  end if;
end $$;

