-- Optional: record the first selling price for each imported product.
-- Comment this out if product_price_history has not been migrated.
select prod_id, null, price, 'catalog-import-2026-10-29'
from public.product;

-- Verify before commit: must be 1,023.
select count(*) as imported_products from public.product;

commit;